mapper.select:
SELECT t.name AS name, SUM(t.stat_value) AS value FROM (
SELECT user_name AS name, COUNT(1) AS stat_value FROM ${tableName} WHERE deleted = 0 AND login_status = 'SUCCESS'
AND login_time >= #{startTime}
AND login_time <= #{endTime}
GROUP BY user_name
) t WHERE t.name IS NOT NULL AND t.name != '' GROUP BY t.name HAVING value > 0 ORDER BY value DESC LIMIT #{limit}
